INSERT INTO `material` VALUES (1,201,'1998-03-04 12:33:37','Fiberglass','Resin impregnated cloth.  Liquid resin is painted on the inside of a one piece mold then cloth is applied for reinforcement.'),(2,201,'1998-03-04 12:29:09','Latex','Flexible rubber.  Liquid rubber is painted on the inside of a one piece mold and removed after hardening.'),(3,201,'1998-03-07 23:46:50','Metal','Used for small parts which need to be fairly strong and hold good detail'),(4,201,'1998-03-07 22:30:31','Pewter','Pewter metal.  Used for small parts which need to be fairly strong and hold good detail.'),(5,201,'1998-03-04 12:11:48','Plastic','This actuallly refers to \"injection molded plastic\".  Liquid is injected into a two part metal mold where it hardens.'),(6,201,'1998-03-04 12:12:37','Resin','Hard plastic.  Made by mixing two liquids (prepolymer and curative) together and pouring into a rubber mold.  After a certain amount of time the liquid \"kicks\" and becomes a solid.'),(8,201,'1998-03-04 12:30:37','Super Sculpey','Sculpting compound which can be hardened by heating.'),(10,201,'1998-03-04 12:23:05','Vinyl','Soft hollow plastic.  Made with hollow one piece metal molds.  Liquid vinyl is poured into the mold then the part is extracted while it is still hot and very flexible.'),(11,201,'1998-03-07 23:47:57','unknown','The information on the material used is not available.'),(12,201,'1998-03-04 12:36:14','Porcelain','Hard white ceramic.'),(13,201,'1998-03-04 12:31:36','Promat','Sculpting compound which can be hardened by heating.'),(14,201,'1998-03-04 12:19:36','Vacuform Plastic','Thin plastic sheets which are heated and made to conform to a one piece mold by applying a vacuum.'),(16,201,'1998-03-07 22:28:10','Bronze','Bronze metal.  Used for unpainted statues.'),(18,201,'1998-03-04 12:31:09','Sculpey 3','Sculpting compound which can be hardened by heating.  Comes in a variety of colors.'),(19,201,'1998-03-04 12:15:31','Cold Cast Porcelain','Resin which has porcelain powder added to it.  This makes it quite a bit more brittle, but forms a very nice surface.'),(20,201,'1998-04-02 15:34:42','Wood','Any type of wood.'),(21,201,'2001-07-10 15:35:50','Clay','Water based clay.');
UNLOCK TABLES;
/*!40000 ALTER TABLE `material` ENABLE KEYS */;

